Tool result: """
LLM Client abstractions for Gemini and Claude APIs.

Uses google-genai SDK (NOT google.generativeai which is deprecated).
"""

import os
import asyncio
from typing import Optional, Callable, Any
from functools import wraps
import logging

logger = logging.getLogger(__name__)


def with_retry(max_attempts: int = 3, base_delay: float = 2.0, exceptions: tuple = (Exception,)):
    """Retry decorator with exponential backoff."""
    def decorator(func: Callable) -> Callable:
        @wraps(func)
        async def wrapper(*args, **kwargs):
            last_error = None
            for attempt in range(max_attempts):
                try:
                    return await func(*args, **kwargs)
                except exceptions as e:
                    last_error = e
                    if attempt < max_attempts - 1:
                        delay = base_delay * (2 ** attempt)
                        logger.warning(f"Attempt {attempt + 1} failed: {e}. Retrying in {delay}s...")
                        await asyncio.sleep(delay)
            raise last_error
        return wrapper
    return decorator


class GeminiClient:
    """
    Gemini API client using google-genai SDK.

    Model: gemini-2.0-flash (fast, cheap)
    """

    MODEL = "gemini-2.0-flash"

    def __init__(self, api_key: Optional[str] = None):
        self.api_key = api_key or os.getenv("GEMINI_API_KEY")
        self._client = None

    def _get_client(self):
        """Lazy initialization of Gemini client."""
        if self._client is None:
            try:
                from google import genai
                self._client = genai.Client(api_key=self.api_key)
            except ImportError:
                # Fallback to httpx-based implementation
                logger.warning("google-genai not installed, using httpx fallback")
                self._client = None
        return self._client

    @with_retry(max_attempts=3, base_delay=2.0, exceptions=(Exception,))
    async def generate(self, prompt: str) -> str:
        """Generate text from prompt."""
        client = self._get_client()

        if client is not None:
            # Use official SDK
            response = await client.aio.models.generate_content(
                model=self.MODEL,
                contents=prompt,
            )
            return response.text or ""
        else:
            # Fallback to REST API
            return await self._generate_via_httpx(prompt)

    async def _generate_via_httpx(self, prompt: str) -> str:
        """Fallback generation using httpx."""
        import httpx

        url = f"https://generativelanguage.googleapis.com/v1beta/models/{self.MODEL}:generateContent"

        payload = {
            "contents": [{
                "parts": [{"text": prompt}]
            }],
            "generationConfig": {
                "temperature": 0.3,
                "maxOutputTokens": 2048
            }
        }

        params = {"key": self.api_key}

        async with httpx.AsyncClient(timeout=60.0) as client:
            response = await client.post(url, json=payload, params=params)
            response.raise_for_status()
            data = response.json()

        # Extract text from response
        text = data.get("candidates", [{}])[0].get("content", {}).get("parts", [{}])[0].get("text", "")
        return text or ""


class ClaudeClient:
    """
    Claude API client for higher quality responses.

    Model: claude-sonnet-4-20250514 (balanced speed/quality)
    """

    DEFAULT_MODEL = "claude-sonnet-4-20250514"

    def __init__(self, api_key: Optional[str] = None):
        self.api_key = api_key or os.getenv("ANTHROPIC_API_KEY")

    @with_retry(max_attempts=3, base_delay=2.0, exceptions=(Exception,))
    async def generate(
        self,
        prompt: str,
        system_prompt: Optional[str] = None,
        max_tokens: int = 4096
    ) -> str:
        """Generate text from prompt."""
        import httpx

        url = "https://api.anthropic.com/v1/messages"

        headers = {
            "x-api-key": self.api_key,
            "anthropic-version": "2023-06-01",
            "content-type": "application/json"
        }

        payload = {
            "model": self.DEFAULT_MODEL,
            "max_tokens": max_tokens,
            "messages": [{
                "role": "user",
                "content": prompt
            }]
        }

        if system_prompt:
            payload["system"] = system_prompt

        async with httpx.AsyncClient(timeout=60.0) as client:
            response = await client.post(url, json=payload, headers=headers)
            response.raise_for_status()
            data = response.json()

        # Extract text from response
        text = data.get("content", [{}])[0].get("text", "")
        return text or ""


# Convenience function for synchronous usage from threading
def run_async(coro):
    """Run async coroutine from synchronous context."""
    loop = asyncio.new_event_loop()
    try:
        return loop.run_until_complete(coro)
    finally:
        loop.close()
